```javascript
const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').split(/\s+/);

let idx = 0;
const N = parseInt(input[idx++], 10);
const A = new Array(N);
for (let i = 0; i < N; i++) A[i] = parseInt(input[idx++], 10);

const INF = Number.MAX_SAFE_INTEGER;
const B = new Array(N);

// passe da esquerda para a direita
let prev = INF;
for (let i = 0; i < N; i++) {
  const cur = A[i] === -1 ? INF : A[i];
  prev = Math.min(cur, prev === INF ? INF : prev + 1);
  B[i] = prev;
}

// passe da direita para a esquerda
let nxt = INF;
for (let i = N - 1; i >= 0; i--) {
  nxt = Math.min(B[i], nxt === INF ? INF : nxt + 1);
  B[i] = nxt;
}

process.stdout.write(B.join(' ') + '\n');
